def resolve_duplicate_active_subscriptions(apps, schema_editor):
    """Leave exactly one ACTIVE subscription per tenant.

    uniq_active_subscription_per_tenant cannot be applied while any tenant holds
    more than one, and this database has several — the defect the constraint exists
    to prevent, already present. Keeps the newest by start_date (tie-broken on
    created_at) and expires the rest, which is the only defensible choice: the most
    recent is what the tenant last paid for.

    Idempotent, and a no-op where the data is already clean.
    """
    Subscription = apps.get_model("onboard", "Subscription")
    seen = {}
    for sub in (
        Subscription.objects.filter(status="active", is_deleted=False)
        .order_by("tenant_id", "-start_date", "-created_at")
    ):
        if sub.tenant_id in seen:
            sub.status = "expired"
            sub.canceled_at = timezone.now()
            sub.superseded_by_id = seen[sub.tenant_id]
            sub.save(update_fields=["status", "canceled_at", "superseded_by"])
            print(f"    expired duplicate subscription {sub.pk} for tenant {sub.tenant_id}")
        else:
            seen[sub.tenant_id] = sub.pk

    # Flush the deferred foreign-key checks this function just queued.
    #
    # Django creates FK constraints as DEFERRABLE INITIALLY DEFERRED on PostgreSQL,
    # so writing `superseded_by` leaves pending trigger events on
    # onboard_subscription. The AddConstraint at the end of this migration is a
    # CREATE UNIQUE INDEX on that same table in the same transaction, and Postgres
    # refuses it with "cannot CREATE INDEX ... because it has pending trigger
    # events".
    #
    # It only bites when this function actually changes something — which is why it
    # went unnoticed: the database it was written against had no duplicates, so the
    # branch never ran. Any environment that *does* have them would have failed the
    # migration outright.
    if schema_editor.connection.vendor == "postgresql":
        with schema_editor.connection.cursor() as cursor:
            cursor.execute("SET CONSTRAINTS ALL IMMEDIATE")


def backfill_cycle_and_snapshot(apps, schema_editor):
    """Give every subscription an end_date, and refreeze its plan terms.

    Two gaps closed at once. end_date was never written by any of the three signup
    paths, so expiry, renewal windows and proration had nothing to compute against.
    And plan_snapshot froze pricing only, so the credit rules and entitlement
    allowances added since are missing from every existing row.

    Historical models carry no custom save() or properties, so the arithmetic is
    inlined here rather than calling Subscription.derive_end_date().
    """
    Subscription = apps.get_model("onboard", "Subscription")
    Plan = apps.get_model("onboard", "Plan")

    deltas = {"monthly": relativedelta(months=1), "yearly": relativedelta(years=1)}
    plans = {p.pk: p for p in Plan.objects.all()}
    entitlements = {}
    PlanEntitlement = apps.get_model("onboard", "PlanEntitlement")
    for e in PlanEntitlement.objects.filter(is_deleted=False):
        entitlements.setdefault(e.plan_id, {})[e.resource] = e.included_quantity

    filled = 0
    for sub in Subscription.objects.all():
        plan = plans.get(sub.plan_id)
        changed = []

        if not sub.end_date and plan:
            start = sub.start_date or sub.created_at or timezone.now()
            sub.end_date = start + deltas.get(plan.billing_cycle, deltas["monthly"])
            changed.append("end_date")

        # Refreeze only when the credit rules are absent; a snapshot that already
        # carries them is a contract and must not be rewritten.
        if plan and "allocated_credits" not in (sub.plan_snapshot or {}):
            base = Decimal(str(plan.base_price or 0))
            disc = (base * Decimal(str(plan.discount_percentage or 0)) / 100).quantize(Decimal("0.01"))
            net = (base - disc).quantize(Decimal("0.01"))
            tax = (net * Decimal(str(plan.tax_percentage or 0)) / 100).quantize(Decimal("0.01"))
            snapshot = dict(sub.plan_snapshot or {})
            snapshot.update({
                "id": str(plan.pk), "code": plan.code, "name": plan.name,
                "description": plan.description,
                "base_price": str(base), "discount_percentage": str(plan.discount_percentage),
                "discount_amount": str(disc), "net_base_price": str(net),
                "tax_percentage": str(plan.tax_percentage), "tax_amount": str(tax),
                "total_price": str((net + tax).quantize(Decimal("0.01"))),
                "currency": plan.currency, "billing_cycle": plan.billing_cycle,
                "plan_type": plan.plan_type,
                "allocated_credits": plan.allocated_credits,
                "cost_per_additional_credit": str(plan.cost_per_additional_credit),
                "max_rollover_credits": plan.max_rollover_credits,
                "allow_rollover_on_renewal": plan.allow_rollover_on_renewal,
                "allow_rollover_on_upgrade": plan.allow_rollover_on_upgrade,
                "allow_rollover_on_downgrade": plan.allow_rollover_on_downgrade,
                "allow_use_after_expiry": plan.allow_use_after_expiry,
                "low_balance_threshold": plan.low_balance_threshold,
                "renews_without_payment": plan.renews_without_payment,
                "entitlements": entitlements.get(plan.pk, {}),
            })
            sub.plan_snapshot = snapshot
            changed.append("plan_snapshot")

        if changed:
            sub.save(update_fields=changed)
            filled += 1
    print(f"    backfilled {filled} subscription(s)")


def backfill_transaction_tenant(apps, schema_editor):
    """Attach a tenant to transactions where one can be resolved.

    Every existing row defaults to transaction_type='onboarding', so the check
    constraint passes regardless. This is for queryability, not correctness.
    """
    Transaction = apps.get_model("onboard", "Transaction")
    TenantUserMapping = apps.get_model("tenant", "TenantUserMapping")
    mapping = dict(
        TenantUserMapping.objects.filter(is_deleted=False).values_list("user_id", "tenant_id")
    )
    updated = 0
    for txn in Transaction.objects.filter(tenant__isnull=True).exclude(user__isnull=True):
        tenant_id = mapping.get(txn.user_id)
        if tenant_id:
            txn.tenant_id = tenant_id
            txn.save(update_fields=["tenant"])
            updated += 1
    print(f"    attached tenant to {updated} transaction(s)")


